const BEAUTY_STOCK_PHOTOS={"maison-beauty-spa":[["photo-1761718210089-ba3bb5ccb54f","A facial treatment in a calm spa setting","kimia kazemi","https://unsplash.com/photos/a-person-receiving-a-facial-treatment-RbIcMsh0NSk"],["photo-1706795034830-de41aee06afa","A relaxing facial massage treatment","Anna Keibalo","https://unsplash.com/photos/a-woman-getting-a-facial-massage-at-a-spa-qybZ2w0CzMw"],["photo-1757689373248-a6cd07328ba5","A warm towel facial treatment at a spa","Stephen Olmo","https://unsplash.com/photos/spa-treatment-with-a-towel-covering-the-face-EpKT9rdinCA"],["photo-1643684391140-c5056cfd3436","A close-up facial skincare treatment","Dominique Rivas","https://unsplash.com/photos/a-woman-getting-a-facial-massage-on-her-face-rWwuf8yKw4Y"],["photo-1639162906614-0603b0ae95fd","A relaxing back massage at a spa","Simon HUMLER","https://unsplash.com/photos/a-woman-getting-a-back-massage-at-a-spa--AakIaAPV0w"]],"the-hair-atelier":[["photo-1723879371709-17908244d70a","A client receiving a professional salon blow-dry","Aditya Sethia","https://unsplash.com/photos/a-woman-getting-her-hair-cut-at-a-salon-jWaK7wl0b1s"],["photo-1634449571010-02389ed0f9b0","A stylist washing a client's hair","Lindsay Cash","https://unsplash.com/photos/a-woman-getting-her-hair-cut-by-a-hair-stylist-Md_DhaFsnCQ"],["photo-1675034743339-0b0747047727","A contemporary hair salon styling floor","Vinicius \"amnx\" Amano","https://unsplash.com/photos/a-woman-getting-her-hair-done-in-a-salon-lK8oXGycy88"],["photo-1774660810725-fb04e002003d","A stylist creating an elegant updo","Alexander Mass","https://unsplash.com/photos/hairstylist-creating-an-updo-for-a-seated-client-g0cSOCHaHiY"],["photo-1768363446104-b8a0c1716600","A barber and client during a precision haircut","Kristina Goncharova","https://unsplash.com/photos/a-barber-cuts-a-clients-hair-in-a-salon-cAN-eg8-Q-Q"]],"forme-nail-brow":[["photo-1632345031435-8727f6897d53","A detailed professional manicure service","Giorgio Trovato","https://unsplash.com/photos/a-woman-getting-her-nails-done-at-a-nail-salon-gb6gtiTZKB8"],["photo-1693776529070-2cdea397595b","A nail technician working on a client's nails","Anna Keibalo","https://unsplash.com/photos/a-woman-getting-her-nails-done-at-a-salon-refgCopwymo"],["photo-1676926606566-58f2e00b592b","A close-up manicure and nail service","Behnaz Kh","https://unsplash.com/photos/a-woman-is-doing-a-manicure-on-her-nails-c9zCtwGsJAA"],["photo-1652869122685-c7792ef56ee2","A modern nail studio with manicure stations","Or Hakim","https://unsplash.com/photos/a-nail-salon-with-chairs-and-a-counter-0jR7w4OW5SQ"],["photo-1571290274554-6a2eaa771e5f","Colourful nail art on a finished manicure","Budka Damdinsuren","https://unsplash.com/photos/womans-nails-with-manicure-jRXxNpA6d_k"]],"the-bridal-edit":[["photo-1774660810791-ffabcc531009","A bridal makeup artist preparing a bride","Alexander Mass","https://unsplash.com/photos/a-bride-getting-her-makeup-done-by-two-artists-hCZiuy70xwk"],["photo-1780540631334-84960e9b1f58","A bride getting ready with her makeup artist","Lucas T Photography","https://unsplash.com/photos/a-bride-getting-makeup-and-hair-done--A9kNJTX2vc"],["photo-1773688199710-040ad7ddac18","A makeup artist applying a bridal look","Alexander Mass","https://unsplash.com/photos/bride-having-makeup-applied-by-a-makeup-artist-OWunn6bxGGg"],["photo-1643224847210-531cffb1aaff","A professional makeup artist preparing a wedding look","Colynary Media","https://unsplash.com/photos/a-woman-getting-her-make-up-done-by-a-professional-makeup-artist-BgKD6HaZKs8"],["photo-1743779622035-c52b3d5267ce","An Indian bride receiving final makeup touches","Raju Kumar","https://unsplash.com/photos/a-bride-is-having-her-makeup-applied-gkLzTqe2aoE"]]};
function beautyPhotoSet(templateKey){const rows=BEAUTY_STOCK_PHOTOS[templateKey]||BEAUTY_STOCK_PHOTOS["maison-beauty-spa"];return rows.map(photo=>({src:"https://images.unsplash.com/"+photo[0]+"?auto=format&fit=crop&w=1400&q=82",alt:photo[1],creator:photo[2],sourcePage:photo[3],license:"Unsplash License"}));}
function beautyPageImages(key,count=2){const page=state.pages.find(p=>p.page_key===key),rows=Array.isArray(page?.page_spec?.media?.images)?page.page_spec.media.images:[],photos=beautyPhotoSet(state.website?.template_key);const pageSeed=Array.from(String(key||"home")).reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7),offset=key==="home"?0:pageSeed%photos.length;return rows.slice(0,count).map((row,index)=>{const photo=photos[(offset+index)%photos.length];return {...row,src:photo.src,alt:photo.alt,source:"Unsplash",creator:photo.creator,sourcePage:photo.sourcePage,license:photo.license};});}

function beautyMediaSection(key){const p=beautyProfile(),imgs=beautyPageImages(key,2),dests=[p.target,p.secondaryTarget];if(!imgs.length)return "";return '<section class="sf-beauty-media"><div class="sf-beauty-media-head"><small>THE VISUAL STORY</small><h2>'+esc(pageCopy(key).title||"A closer look")+'</h2></div><div class="sf-beauty-media-grid">'+imgs.map((im,i)=>'<a href="'+pageUrl(dests[i]||p.target)+'" class="sf-beauty-media-card"><img loading="lazy" decoding="async" src="'+esc(im.src)+'" alt="'+esc(im.alt||"Original beauty illustration")+'"><span>0'+(i+1)+' · '+esc(im.scene||"Studio story")+'</span></a>').join("")+'</div></section>';}
function beautyHome(){const p=beautyProfile(),copy=pageCopy("home"),imgs=beautyPageImages("home",5),services=p.services.map((x,i)=>'<a class="sf-beauty-service-card" href="'+pageUrl(p.servicePages[i]||p.target)+'"><img loading="lazy" decoding="async" src="'+esc(imgs[i+1]?.src||imgs[0]?.src||beautyArtSrc(p.brand+i,"service"))+'" alt="'+esc(imgs[i+1]?.alt||x[0])+'"><span>0'+(i+1)+' / SERVICE</span><h3>'+esc(x[0])+'</h3><p>'+esc(x[1])+'</p><b>Explore ↗</b></a>').join("");return '<div class="sf-beauty sf-beauty--'+esc(state.website.template_key)+'"><section class="sf-beauty-hero"><div class="sf-beauty-hero-copy"><small>'+esc(p.eyebrow)+'</small><h1>'+esc(copy.heading&&copy.heading!=="Home"?copy.heading:p.hero)+'</h1><p>'+esc(copy.description||p.copy)+'</p><div class="sf-beauty-actions"><a class="sf-beauty-primary" href="'+pageUrl(p.target)+'">'+esc(p.primary)+' ↗</a><a class="sf-beauty-secondary" href="'+pageUrl(p.secondaryTarget)+'">'+esc(p.secondary)+'</a></div><div class="sf-beauty-promises">'+p.promise.map(x=>'<span>✦ '+esc(x)+'</span>').join("")+'</div></div><a class="sf-beauty-hero-art" href="'+pageUrl(p.target)+'"><img src="'+esc(imgs[0]?.src||beautyArtSrc(p.brand,"hero"))+'" alt="'+esc(imgs[0]?.alt||"Beauty studio photography")+'" fetchpriority="high" decoding="async"><span>Explore the studio ↗</span></a></section><section class="sf-beauty-services"><div class="sf-beauty-section-head"><small>THE SERVICE EDIT</small><h2>Considered services, a personal approach.</h2><p>'+esc(p.copy)+'</p></div><div class="sf-beauty-service-grid">'+services+'</div></section><section class="sf-beauty-next"><div><small>YOUR NEXT STEP</small><h2>Start with a conversation.</h2><p>Share your preferred service and time. The studio will review your request and confirm availability.</p></div><a href="'+pageUrl(p.secondaryTarget)+'">'+esc(p.secondary)+' ↗</a></section></div>';}
function beautyBookingPage(){const p=beautyProfile(),key=state.page,copy=pageCopy(key),imgs=beautyPageImages(key,2),showcase=preview||state.website.settings?.showcase_mode===true||state.website.settings?.appointments_enabled===false||state.website.settings?.enquiries_enabled===false;return '<section class="sf-beauty-booking"><div class="sf-beauty-booking-intro"><small>'+esc(p.eyebrow)+'</small><h1>'+esc(copy.heading||"Request an appointment")+'</h1><p>'+esc(copy.description||"Share the service and time you prefer. The studio will review your request and contact you to confirm availability.")+'</p><div class="sf-beauty-booking-art">'+imgs.map(im=>'<img loading="lazy" src="'+esc(im.src)+'" alt="'+esc(im.alt||"Original beauty artwork")+'">').join("")+'</div><div class="sf-beauty-request-note">Submitting this form sends an appointment request only. It does not reserve or confirm a time. The business must confirm availability and any service requirements.</div></div><form id="sfBeautyBookingForm" class="sf-beauty-booking-form"><div class="sf-beauty-form-grid"><label>Your name *<input name="name" autocomplete="name" required maxlength="160"></label><label>Phone number *<input name="phone" type="tel" autocomplete="tel" required maxlength="40"></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254"></label><label>Service *<select name="service" required><option value="">Choose a service</option>'+p.services.map(x=>'<option value="'+esc(x[0])+'">'+esc(x[0])+'</option>').join("")+'</select></label><label>Preferred date *<input type="date" name="preferred_date" required></label><label>Preferred time *<select name="preferred_time" required><option value="">Choose a time window</option><option>Morning</option><option>Afternoon</option><option>Evening</option><option>Flexible</option></select></label><label>Preferred stylist / artist<input name="provider_preference" maxlength="140" placeholder="Optional"></label>'+(state.website.template_key==="the-bridal-edit"?'<label>Event date<input type="date" name="event_date"></label><label class="wide">Venue or getting-ready location<input name="venue" maxlength="180"></label><label>Wedding-party size<input type="number" name="party_size" min="1" max="100"></label>':'')+'<label class="wide">Anything the studio should know?<textarea name="message" rows="4" maxlength="1600"></textarea></label><label class="sf-beauty-consent wide"><input type="checkbox" name="consent" required><span>I agree that the business may contact me about this request.</span></label></div><button id="sfBeautyBookingSubmit" class="sf-beauty-primary" type="submit" '+(showcase?'disabled':'')+'>Send appointment request ↗</button><p id="sfBeautyBookingStatus" class="sf-beauty-form-status" role="status" aria-live="polite">'+(showcase?'Showcase preview: requests are disabled.':"The studio will confirm the request separately.")+'</p></form></section>';}
function beautyContentPage(){const key=state.page,page=state.pages.find(p=>p.page_key===key),spec=page?.page_spec||{},copy=pageCopy(key),content=docFor(key)?.content||spec.content||{},p=beautyProfile(),title=copy.title||page?.title||key.replace(/-/g," "),description=copy.description||content.description||"Explore this part of the studio's services, approach and guest information.",blocks=Array.isArray(content.blocks)?content.blocks:[],listings=Array.isArray(content.listings)?content.listings:[],cards=(listings.length?listings:page?.page_type==="directory"?p.services:[]).map((item,i)=>'<article class="sf-beauty-content-card"><span>0'+(i+1)+'</span><h3>'+esc(item.title||item[0]||"Service information")+'</h3><p>'+esc(item.description||item[1]||"Ask the studio for current details.")+'</p>'+(item.price_label?'<small>'+esc(item.price_label)+'</small>':'')+'</article>').join(""),blockHtml=blocks.map(block=>'<section class="sf-beauty-copy-block"><h2>'+esc(block.heading||title)+'</h2>'+(block.paragraphs||[]).map(par=>'<p>'+esc(par)+'</p>').join("")+(block.bullets?.length?'<ul>'+block.bullets.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':'')+'</section>').join("");return '<div class="sf-beauty sf-beauty--'+esc(state.website.template_key)+'"><section class="sf-beauty-page-hero"><small>'+esc(p.eyebrow)+'</small><h1>'+esc(title)+'</h1><p>'+esc(description)+'</p><a class="sf-beauty-primary" href="'+pageUrl(p.secondaryTarget)+'">'+esc(p.secondary)+' ↗</a></section>'+beautyMediaSection(key)+(cards?'<section class="sf-beauty-content-grid">'+cards+'</section>':'')+blockHtml+'<section class="sf-beauty-next"><div><small>NEED MORE INFORMATION?</small><h2>Talk with the studio.</h2><p>Service details, current pricing, provider profiles and policies should be confirmed by the business.</p></div><a href="'+pageUrl(p.secondaryTarget)+'">'+esc(p.secondary)+' ↗</a></section></div>';}
function beautyPage(){const key=state.page,p=beautyProfile();if(key==="home")return beautyHome();if([p.bookingPage,"book-appointment","appointment-request","consultation","book-consultation","availability"].includes(key))return beautyBookingPage();return beautyContentPage();}
function beautyFooter(){const p=beautyProfile(),brand=state.website.brand?.name||p.brand;return '<footer class="sf-footer sf-beauty-footer"><div class="sf-footer-inner"><div><h3>'+esc(brand)+'</h3><p>'+esc(p.copy)+'</p><small>Appointment requests are reviewed by the business. A request is not a confirmed booking.</small><small>Photography: Unsplash contributors · Unsplash License.</small></div><div><h4>Explore</h4><div class="sf-footer-links"><a href="'+pageUrl(p.target)+'">'+esc(p.primary)+'</a><a href="'+pageUrl(p.galleryPage)+'">Gallery</a><a href="'+pageUrl("faq")+'">FAQs</a></div></div><div><h4>Plan your visit</h4><div class="sf-footer-links"><a href="'+pageUrl(p.secondaryTarget)+'">'+esc(p.secondary)+'</a><a href="'+pageUrl("locations")+'">Locations</a><a href="'+pageUrl("contact")+'">Contact</a></div></div><div><h4>Information</h4><div class="sf-footer-links"><a href="'+pageUrl("booking-policy")+'">Booking policy</a><a href="'+pageUrl("cancellation-policy")+'">Cancellation policy</a><a href="'+pageUrl("privacy")+'">Privacy</a><a href="'+pageUrl("terms")+'">Terms</a></div></div></div><div class="sf-footer-bottom">© '+new Date().getFullYear()+' '+esc(brand)+'. All rights reserved.</div></footer>';}
