const seed=Array.from(String(id||scene||"art")).reduce((a,c)=>((a*33)+c.charCodeAt(0))>>>0,5381),cx=360+(seed%360),cy=320+((seed>>>5)%150),tilt=(seed%19)-9,accent=["#6E8D58","#D9A85D","#B96B52","#8097A3"][seed%4];
const plate='<ellipse cx="590" cy="610" rx="350" ry="55" fill="'+p[2]+'" opacity=".09"/><ellipse cx="'+cx+'" cy="'+cy+'" rx="300" ry="205" fill="#fff" stroke="'+p[2]+'" stroke-opacity=".16" stroke-width="12"/><ellipse cx="'+cx+'" cy="'+cy+'" rx="245" ry="155" fill="'+p[0]+'" stroke="'+p[1]+'" stroke-width="9"/>';
