function restaurantImageStory(key,count=4,start=0){const imgs=restaurantPageImages(key,4).slice(start,start+count),title=pageCopy(key).title||"A closer look";if(!imgs.length)return "";return '<section class="sf-restaurant-visual"><div class="sf-restaurant-visual-heading"><small>VISUAL STORY</small><h2>'+esc(title)+'</h2><p>Original illustrations created for this page, with each visual linked only to another page on this website.</p></div><div class="sf-restaurant-visual-grid">'+imgs.map((im,i)=>'<a class="sf-restaurant-visual-card '+(i%2?"is-offset":"")+'" href="'+pageUrl(i%2?"contact":restaurantProfile().target)+'"><img loading="lazy" decoding="async" src="'+esc(im.src)+'" alt="'+esc(im.alt||title)+'"><span>0'+(i+1)+' · '+esc(title)+'</span></a>').join("")+'</div></section>';}
