 return pageHead("APPOINTMENT REQUEST",copy.heading||"Request an appointment",copy.description)+'<div class="sf-health-booking"><section><h2>A request, not a confirmed booking.</h2><p>Share contact and scheduling details only. Do not enter symptoms, diagnoses, medication lists or medical records.</p><ul><li>The provider reviews your request.</li><li>The provider confirms availability and next steps.</li><li>Do not use this form for emergencies.</li></ul></section><form id="sfAppointmentForm"><label>Name<input name="name" required maxlength="120" autocomplete="name"></label><label>Phone<input name="phone" required maxlength="30" autocomplete="tel"></label><label>Email (optional)<input name="email" type="email" maxlength="160" autocomplete="email"></label><label>Service or department<select name="service" required><option value="">Choose a service</option>'+opts+'</select></label><label>Preferred date<input name="preferred_date" type="date" required></label><label>Preferred time<select name="preferred_time" required><option value="">Choose a time</option><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label><label>Preferred visit type<select name="consultation_mode"><option>In person (confirm with provider)</option><option>Remote consultation (only if enabled)</option><option>Phone call</option></select></label><label class="sf-health-wide">Scheduling note (optional)<textarea name="note" maxlength="500" placeholder="Do not include medical history or symptoms."></textarea></label><label class="sf-health-wide"><input type="checkbox" name="consent" required> I agree the provider may use these contact details to respond to this request.</label><button class="sf-btn sf-health-wide" id="sfApptSubmit" type="submit" '+(locked?"disabled":"")+'>'+(preview||state.website.status!=="published"?"Preview only — publishing required":"Requests disabled until healthcare compliance is verified")+'</button><p id="sfApptStatus" class="sf-help sf-health-wide" role="status" aria-live="polite"></p></form></div><p class="sf-health-safety">'+(preview||state.website.status!=="published"?"Private preview only; no request is transmitted.":!intakeReady?"Appointment intake is disabled until provider verification, secure handling and applicable local data-residency requirements have been confirmed by the operator.":"Submitting this request does not confirm an appointment. The provider must contact you.")+'</p>';
