async function submitAppointment(e){
 e.preventDefault();const form=e.currentTarget,data=new FormData(form),status=root.querySelector("#sfApptStatus"),button=root.querySelector("#sfApptSubmit");
 if(state.website.settings?.showcase_mode){status.textContent="Template showcase only. Appointment requests are disabled; no information was sent.";return;}
 const settings=state.website.settings||{},intakeReady=settings.healthcare_intake_enabled===true&&settings.healthcare_data_residency_verified===true&&settings.healthcare_provider_verified===true;if(preview||state.website.status!=="published"||!intakeReady){status.textContent="Appointment intake is disabled until the provider verifies credentials, secure handling and applicable local data-residency requirements. No request was sent.";return;}
 const name=String(data.get("name")||"").trim(),phone=String(data.get("phone")||"").trim(),service=String(data.get("service")||"").trim(),date=String(data.get("preferred_date")||"").trim(),time=String(data.get("preferred_time")||"").trim();
 if(!name||!phone||!service||!date||!time||!data.get("consent")){status.textContent="Complete required fields and consent.";return;}
 button.disabled=true;button.textContent="Sending request…";
 try{const business={company_name:"Patient appointment request",contact_name:name,phone,email:String(data.get("email")||"").trim(),business_type:"healthcare-appointment"};const items=[{description:"Appointment request: "+service,quantity:1,service,preferred_date:date,preferred_time:time,consultation_mode:String(data.get("consultation_mode")||"")}];const notes=("Non-urgent request, not a confirmed booking. No medical history collected. Scheduling note: "+String(data.get("note")||"").trim()).slice(0,2000);const result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,notes);status.textContent=(result?.message||"Request received.")+" Reference: "+(result?.quote_number||"saved")+". The provider will confirm.";form.reset();}
 catch(err){status.textContent=err.message||"Request could not be sent. Contact the provider.";}finally{button.disabled=false;button.textContent="Send appointment request";}
}
function healthcarePage(){
 const k=state.page;
 if(k==="home")return healthcareHome();
 if(["appointment","appointments","booking","request-consultation"].includes(k))return healthcareAppointmentPage();
 if(["departments","tests","test-categories","specialties","services","care-categories","health-packages"].includes(k))return healthcareDirectoryPage(k);
 if(["doctors","clinicians","clinical-team"].includes(k))return healthcareProvidersPage(k);
 if(["emergency-information","emergency-guidance"].includes(k))return pageHead("IMPORTANT SAFETY INFORMATION","Urgent and emergency care","This website is not monitored for emergencies.")+'<div class="sf-health-emergency"><p>If someone may be in immediate danger, contact your local emergency service now. Do not wait for a website form or appointment request to be reviewed.</p></div>';
 if(["locations","location","location-detail"].includes(k)){const brand=state.website.brand||{};return pageHead("VISIT INFORMATION","Find a location","Use only the provider's verified address and opening information.")+'<div class="sf-health-content"><h2>Location details</h2><p>'+(brand.address?esc(brand.address):"The operator has not added a verified address yet.")+'</p><p>'+(brand.phone?'<a href="tel:'+esc(brand.phone)+'">'+esc(brand.phone)+'</a>':"Add a verified contact number in website settings.")+'</p><p>'+(brand.email?'<a href="mailto:'+esc(brand.email)+'">'+esc(brand.email)+'</a>':"Add a contact email in website settings.")+'</p></div>';}
 return healthcareContentPage(k);
}

